data.diagramCode:
classDiagram
    ComplexNumber --|> RectangularForm
    ComplexNumber --|> PolarForm
    ComplexNumber --|> EulerForm

    class ComplexNumber {
        +z
    }
    class RectangularForm {
        +x : Real Part
        +y : Imaginary Part
        +z = x + iy
    }
    class PolarForm {
        +r : Modulus (sqrt(x^2+y^2))
        +theta : Argument (atan(y/x))
        +z = r(cos(theta) + i*sin(theta))
    }
    class EulerForm {
        +r : Modulus
        +theta : Argument
        +z = r*e^(i*theta)
    }
